      ro: ["Orașul Stellenbosch a fost întemeiat în anul 1679 de Simon van der Stel.", "Prima rută a vinului din Africa de Sud a fost stabilită aici în anul 1971.", "Există peste 150 de domenii viticole active în districtul Stellenbosch.", "Soiul de struguri Pinotage a fost creat la Universitatea Stellenbosch în 1925.", "Stellenbosch este al doilea cel mai vechi oraș fondat de europeni în țară.", "Universitatea locală a fost transformată în instituție de stat în 1918."],
      en: ["Stellenbosch was founded in 1679, named after Governor Simon van der Stel.", "The first official South African Wine Route was launched here in 1971.", "The region contains more than 150 wine farms open to the public.", "Pinotage, South Africa's signature grape, was cross-bred here in 1925.", "The town is known as 'Eikestad' (City of Oaks) due to its many oak trees.", "Stellenbosch University is one of the oldest and most prestigious in Africa."],
      es: ["Fundación: 1679 por colonos holandeses", "Distancia a Ciudad del Cabo: 50 km", "Número de bodegas: más de 200", "Variedades principales: Cabernet Sauvignon, Chardonnay", "Altitud: 100-300 m sobre el nivel del mar", "Producción anual de vino: aprox. 300.000 hectolitros"],
      pt: ["Fundação: 1679 por colonos holandeses", "Distância da Cidade do Cabo: 50 km", "Número de quintas: mais de 200", "Castas principais: Cabernet Sauvignon, Chardonnay", "Altitude: 100-300 m acima do nível do mar", "Produção anual de vinho: aprox. 300.000 hectolitros"],
      fr: ["Fondation : 1679 par des colons néerlandais", "Distance du Cap : 50 km", "Nombre de domaines : plus de 200", "Cépages principaux : Cabernet Sauvignon, Chardonnay", "Altitude : 100-300 m au-dessus du niveau de la mer", "Production annuelle de vin : env. 300 000 hectolitres"],
