    description: { de: "Vergnügungspark, der das Leben in Johannesburg während des Goldrausches nachstellt.", hu: "Vidámpark, amely az aranyláz idején zajló johannesburgi életet mutatja be.", ro: "Parc de distracții care recreează viața din Johannesburg în timpul goanei după aur.", en: "Amusement park recreating life in Johannesburg during the gold rush." , es: "Parque de atracciones que recrea la vida en Johannesburgo durante la fiebre del oro.", pt: "Parque de diversões que recria a vida em Joanesburgo durante a corrida do ouro.", fr: "Parc d'attractions qui recrée la vie à Johannesburg pendant la ruée vers l'or."},
