      ro: ["Fondată în 1977 ca fermă de crocodili", "Adăpostește peste 90 de specii de animale", "Fundația pentru Gheparzi creată în 1988", "Acreditare oficială PAAZA pentru standarde", "Programe avansate de reproducere asistată", "Situată în inima regiunii Klein Karoo"],
      en: ["Founded in 1977 as a crocodile farm", "Houses more than 90 animal species", "Cheetah Preservation Foundation started 1988", "Accredited by the PAAZA organization", "Leader in captive cheetah breeding", "Key tourist site in the Klein Karoo"],
      es: ["El rancho fue fundado en 1977.", "La superficie es de 10 hectáreas.", "Más de 100 animales viven en el rancho.", "Las caricias a guepardos se realizan bajo supervisión.", "El rancho alberga 5 de las 9 subespecies de león.", "Anualmente visitan el rancho unos 100.000 turistas."],
      pt: ["O rancho foi fundado em 1977.", "A área é de 10 hectares.", "Mais de 100 animais vivem no rancho.", "A interação com guepardos é realizada sob supervisão.", "O rancho abriga 5 das 9 subespécies de leão.", "Anualmente, cerca de 100.000 turistas visitam o rancho."],
      fr: ["Le ranch a été fondé en 1977.", "La superficie est de 10 hectares.", "Plus de 100 animaux vivent au ranch.", "Le contact avec les guépards se fait sous surveillance.", "Le ranch abrite 5 des 9 sous-espèces de lions.", "Chaque année, environ 100 000 touristes visitent le ranch."],
