    descriptionAdvanced: {
      de: "Cheetah Outreach ist eine bedeutende Naturschutzorganisation mit Sitz in Somerset West bei Kapstadt, die sich dem Überleben des afrikanischen Geparden in der freien Wildbahn verschrieben hat. Gegründet im Jahr 1997 von Annie Beckhelling, reagierte die Einrichtung auf den drastischen Rückgang der Gepardenpopulationen durch Konflikte mit Viehzüchtern. Das Herzstück ihrer Arbeit ist das 'Livestock Guarding Dog Program', bei dem Anatolische Hirtenhunde gezüchtet und an Farmer abgegeben werden, um Raubtiere ohne Gewalt vom Vieh fernzuhalten. In der Einrichtung selbst leben Geparden, die als Botschafter dienen, um Besuchern die ökologische Bedeutung und die Gefährdung dieser schnellsten Landsäugetiere näherzubringen. Neben Geparden beherbergt das Zentrum auch andere kleine Raubtiere wie Servale und Erdmännchen. Cheetah Outreach finanziert sich durch Bildungsführungen und private Spenden und betreibt umfangreiche Feldforschung in den nördlichen Provinzen Südafrikas. Die Arbeit der Organisation hat dazu beigetragen, die Akzeptanz von Raubtieren in landwirtschaftlich genutzten Gebieten erheblich zu steigern.",
      hu: "A Cheetah Outreach egy meghatározó természetvédelmi szervezet, amely a Fokváros melletti Somerset Westben található, és az afrikai gepárdok vadonbeli fennmaradásáért küzd. Az alapítványt 1997-ben hozta létre Annie Beckhelling, válaszul a gepárdállomány drasztikus csökkenésére, amelyet elsősorban a farmerekkel való konfliktusok okoztak. A szervezet egyik legsikeresebb kezdeményezése a 'Livestock Guarding Dog Program', amelynek keretében anatóliai juhászkutyákat tenyésztenek és adnak át gazdáknak a ragadozók távol tartására. A központban élő gepárdok nagykövetként szolgálnak, segítve a látogatókat a faj különleges igényeinek és veszélyeztetettségének megértésében. A gepárdok mellett más kisebb ragadozók, például szerválok és szurikáták is láthatók a területen. A Cheetah Outreach kizárólag adományokból és látogatói hozzájárulásokból tartja fenn magát, miközben folyamatos terepmunkát végez Dél-Afrika északi tartományaiban. Munkájuknak köszönhetően jelentősen csökkent a gepárdok elleni támadások száma a mezőgazdasági területeken.",
      ro: "Cheetah Outreach este o organizație de conservare de prestigiu, situată în Somerset West lângă Cape Town, dedicată supraviețuirii ghepardului african în sălbăticie. Fondată în 1997 de Annie Beckhelling, instituția a apărut ca răspuns la declinul alarmant al populațiilor de gheparzi din cauza conflictelor cu fermierii. Programul lor fanion, „Livestock Guarding Dog Program”, presupune creșterea și distribuirea câinilor ciobănești anatolieni către fermieri pentru a proteja șeptelul fără a recurge la uciderea prădătorilor. În cadrul centrului, gheparzii rezidenți acționează ca ambasadori, oferind publicului șansa de a înțelege biologia și provocările cu care se confruntă cel mai rapid animal terestru. Pe lângă gheparzi, vizitatorii pot vedea și alte mamifere mici, precum servali și suricate. Cheetah Outreach este susținută integral prin tururi educaționale și donații, investind masiv în cercetarea de teren în nordul Africii de Sud. Succesul lor este măsurat prin reducerea semnificativă a mortalității gheparzilor în zonele agricole și prin creșterea gradului de conștientizare ecologică la nivel global.",
      en: "Cheetah Outreach is a vital non-profit conservation community based in Somerset West, near Cape Town, dedicated to the survival of the free-ranging African cheetah. Founded in 1997 by Annie Beckhelling, the organization was established to address the rapid decline of cheetah populations caused by conflict with livestock farmers. Their most impactful initiative is the Livestock Guarding Dog Program, which breeds and places Anatolian Shepherd dogs with farmers to deter predators non-lethally. The facility houses several ambassador cheetahs that help educate the public about the species' specialized biology and their critical status in the wild. In addition to cheetahs, the center provides a home for other smaller predators such as servals, caracals, and meerkats. Cheetah Outreach relies on educational tours and public donations to fund its extensive field research and community outreach programs in South Africa's northern provinces. The organization's efforts have significantly improved the coexistence between humans and large predators in agricultural landscapes. It remains a key destination for wildlife enthusiasts and those interested in practical conservation solutions.",
      es: "Cheetah Outreach es un proyecto de conservación de guepardos cerca de Ciudad del Cabo, Sudáfrica. Fue fundado en 1997 para crear conciencia sobre la protección de los guepardos. El centro alberga guepardos nacidos en cautiverio o que no pueden ser liberados en la naturaleza. Los visitantes pueden participar en visitas guiadas y ver a los animales de cerca. Cheetah Outreach también ofrece programas educativos para comunidades locales. El proyecto trabaja con agricultores para reducir los conflictos entre humanos y animales. La población de guepardos en Sudáfrica está gravemente amenazada, con menos de 1.000 animales en libertad.",
      pt: "Cheetah Outreach é um projeto de conservação de guepardos perto da Cidade do Cabo, na África do Sul. Foi fundado em 1997 para aumentar a consciencialização sobre a proteção dos guepardos. O centro abriga guepardos nascidos em cativeiro ou que não podem ser libertados na natureza. Os visitantes podem participar em visitas guiadas e ver os animais de perto. A Cheetah Outreach também oferece programas educacionais para comunidades locais. O projeto trabalha com agricultores para reduzir conflitos entre humanos e animais. A população de guepardos na África do Sul está gravemente ameaçada, com menos de 1.000 animais em liberdade.",
      fr: "Cheetah Outreach est un projet de conservation des guépards près du Cap, en Afrique du Sud. Il a été fondé en 1997 pour sensibiliser à la protection des guépards. Le centre abrite des guépards nés en captivité ou qui ne peuvent être relâchés dans la nature. Les visiteurs peuvent participer à des visites guidées et voir les animaux de près. Cheetah Outreach propose également des programmes éducatifs pour les communautés locales. Le projet collabore avec des agriculteurs pour réduire les conflits entre l'homme et l'animal. La population de guépards en Afrique du Sud est gravement menacée, avec moins de 1 000 individus à l'état sauvage.",
    },
